+  // Pass 2: scan actual painted pixels and center by real bitmap bounds.
+  const image = ctx.getImageData(0, 0, size, size);
+  const alpha = image.data;
+  let top = -1;
+  let bottom = -1;
+  const rowStride = size * 4;
+  const alphaThreshold = 10;
