def _cleanup_local_captchas(now: Optional[datetime] = None) -> None:
    now_dt = now or _now_utc()
    with _local_captcha_lock:
        expired_ids = [
            cid
            for cid, item in _local_captcha_store.items()
            if item.get("expires_at") is None or item["expires_at"] < now_dt
        ]
        for cid in expired_ids:
            _local_captcha_store.pop(cid, None)


def create_local_captcha_challenge() -> LocalCaptchaChallengeResponse:
    a = random.randint(1, 9)
    b = random.randint(1, 9)
    captcha_id = str(uuid.uuid4())
    answer = str(a + b)
    expires_at = _now_utc() + timedelta(seconds=LOCAL_CAPTCHA_TTL_SECONDS)
    with _local_captcha_lock:
        _local_captcha_store[captcha_id] = {"answer": answer, "expires_at": expires_at}
    return LocalCaptchaChallengeResponse(
        captcha_id=captcha_id,
        question=f"{a} + {b} = ?",
        expires_in_seconds=LOCAL_CAPTCHA_TTL_SECONDS,
    )


def verify_local_captcha(captcha_id: Optional[str], answer: Optional[str]) -> bool:
    if not captcha_id or not answer:
        return False
    _cleanup_local_captchas()
    with _local_captcha_lock:
        item = _local_captcha_store.get(captcha_id)
        if not item:
            return False
        if item["expires_at"] < _now_utc():
            _local_captcha_store.pop(captcha_id, None)
            return False
        ok = str(item["answer"]).strip() == str(answer).strip()
        if ok:
            _local_captcha_store.pop(captcha_id, None)
        return ok

input.new_string:
def create_local_captcha_challenge() -> LocalCaptchaChallengeResponse:
    """无状态本地验证码：JWT 存在 captcha_id 中，适配多 worker / 云端扩容。"""
    a = random.randint(1, 9)
    b = random.randint(1, 9)
    ans = str(a + b)
    now = _now_utc()
    exp = now + timedelta(seconds=LOCAL_CAPTCHA_TTL_SECONDS)
    payload: Dict[str, Any] = {
        "t": LOCAL_CAPTCHA_JWT_TYP,
        "ans": ans,
        "iat": int(now.timestamp()),
        "exp": int(exp.timestamp()),
    }
    token = jwt.encode(payload, settings.jwt_secret_key, algorithm=JWT_ALG)
    return LocalCaptchaChallengeResponse(
        captcha_id=token,
        question=f"{a} + {b} = ?",
        expires_in_seconds=LOCAL_CAPTCHA_TTL_SECONDS,
    )


def verify_local_captcha(captcha_id: Optional[str], answer: Optional[str]) -> bool:
    if not captcha_id or answer is None or str(answer).strip() == "":
        return False
    try:
        payload = jwt.decode(
            captcha_id.strip(),
            settings.jwt_secret_key,
            algorithms=[JWT_ALG],
        )
        if payload.get("t") != LOCAL_CAPTCHA_JWT_TYP:
            return False
        return str(payload.get("ans", "")).strip() == str(answer).strip()
    except JWTError:
        return False

