+import React from "react";
+import { Card, Col, Progress, Row, Segmented, Space, Statistic, Typography } from "antd";
+
+type PeriodKey = "7d" | "30d";
+
+function buildSeries(days: number) {
+  const labels: string[] = [];
+  const values: number[] = [];
+  const now = new Date();
+  for (let i = days - 1; i >= 0; i -= 1) {
+    const d = new Date(now);
+    d.setDate(now.getDate() - i);
+    labels.push(`${d.getMonth() + 1}/${d.getDate()}`);
+    const base = days === 7 ? 22 : 18;
+    const wave = Math.sin((days - i) / 2.3) * 6 + Math.cos((days - i) / 3.9) * 4;
+    const trend = days === 30 ? (days - i) * 0.4 : (days - i) * 0.7;
+    values.push(Math.max(6, Math.round(base + wave + trend)));
+  }
+  return { labels, values };
+}
+
+const JourneyInsightsPage: React.FC = () => {
+  const [period, setPeriod] = React.useState<PeriodKey>("7d");
+
+  const current = React.useMemo(() => buildSeries(period === "7d" ? 7 : 30), [period]);
+  const previous = React.useMemo(() => {
+    const vals = current.values.map((v, idx) => Math.max(4, Math.round(v * (0.76 + (idx % 5) * 0.03))));
+    return { labels: current.labels, values: vals };
+  }, [current]);
+
+  const currentTotal = current.values.reduce((acc, v) => acc + v, 0);
+  const previousTotal = previous.values.reduce((acc, v) => acc + v, 0);
+  const deltaPct = previousTotal === 0 ? 0 : ((currentTotal - previousTotal) / previousTotal) * 100;
+
+  const maxValue = Math.max(...current.values, ...previous.values, 1);
+  const avgCurrent = Math.round(currentTotal / current.values.length);
+  const avgPrevious = Math.round(previousTotal / previous.values.length);
+
+  const stepProgress = [
+    { title: "Step 1 · 准备论文", desc: "上传论文并完成分段、字数统计。", value: 100 },
+    { title: "Step 2 · 润色与降重", desc: "按段落优化，持续对比原文与结果。", value: 78 },
+    { title: "Step 3 · 导出与提交", desc: "完成质检后导出全文草稿。", value: 64 }
+  ];
+
+  return (
+    <Space direction="vertical" size={16} style={{ width: "100%" }}>
+      <Card
+        title="使用旅程分析"
+        extra={
+          <Segmented
+            value={period}
+            onChange={(v) => setPeriod(v as PeriodKey)}
+            options={[
+              { label: "近 7 天", value: "7d" },
+              { label: "近 30 天", value: "30d" }
+            ]}
+          />
+        }
+      >
+        <Row gutter={[16, 16]}>
+          <Col xs={24} md={8}>
+            <Statistic title="当前周期总字数" value={currentTotal} suffix="字" />
+          </Col>
+          <Col xs={24} md={8}>
+            <Statistic title="上个周期总字数" value={previousTotal} suffix="字" />
+          </Col>
+          <Col xs={24} md={8}>
+            <Statistic
+              title="环比变化"
+              value={Number(deltaPct.toFixed(1))}
+              suffix="%"
+              valueStyle={{ color: deltaPct >= 0 ? "#3f8600" : "#cf1322" }}
+            />
+          </Col>
+        </Row>
+      </Card>
+
+      <Card title="日期对比统计图">
+        <Space direction="vertical" size={10} style={{ width: "100%" }}>
+          {current.labels.map((label, idx) => {
+            const cur = current.values[idx];
+            const prev = previous.values[idx];
+            return (
+              <Row key={label} gutter={8} align="middle">
+                <Col xs={4} md={3}>
+                  <Typography.Text type="secondary">{label}</Typography.Text>
+                </Col>
+                <Col xs={10} md={10}>
+                  <Progress
+                    percent={Math.round((cur / maxValue) * 100)}
+                    showInfo={false}
+                    strokeColor="#4f7cff"
+                    trailColor="rgba(79,124,255,0.12)"
+                  />
+                </Col>
+                <Col xs={4} md={3}>
+                  <Typography.Text>{cur} 字</Typography.Text>
+                </Col>
+                <Col xs={10} md={6}>
+                  <Typography.Text type="secondary">上周期：{prev} 字</Typography.Text>
+                </Col>
+              </Row>
+            );
+          })}
+        </Space>
+      </Card>
+
+      <Row gutter={[16, 16]}>
+        <Col xs={24} lg={12}>
+          <Card title="我的使用旅程">
+            <Space direction="vertical" size={12} style={{ width: "100%" }}>
+              {stepProgress.map((step) => (
