# 在本机启动 OpenAI 兼容推理（merged）。请先按 README 创建 .venv-serve 并安装依赖。
$ErrorActionPreference = "Stop"
$Root = Split-Path -Parent $MyInvocation.MyCommand.Path
Set-Location $Root

$py = Join-Path $Root ".venv-serve\Scripts\python.exe"
if (-not (Test-Path $py)) {
  Write-Host "未找到 $py ，请先: python -m venv .venv-serve && .\.venv-serve\Scripts\pip install -r requirements-serve.txt" -ForegroundColor Yellow
  exit 1
}

if (-not $env:INFERENCE_API_KEY) {
  Write-Host "建议先设置环境变量 INFERENCE_API_KEY 为强随机串，并与网站后端 REMOTE_INFERENCE_API_KEY 一致。" -ForegroundColor Yellow
}

$env:MERGED_MODEL_DIR = if ($env:MERGED_MODEL_DIR) { $env:MERGED_MODEL_DIR } else { Join-Path $Root "merged" }
$env:SERVE_HOST = if ($env:SERVE_HOST) { $env:SERVE_HOST } else { "127.0.0.1" }
$env:SERVE_PORT = if ($env:SERVE_PORT) { $env:SERVE_PORT } else { "8010" }

Write-Host "MERGED_MODEL_DIR=$($env:MERGED_MODEL_DIR)"
Write-Host "SERVE $($env:SERVE_HOST):$($env:SERVE_PORT)"
& $py (Join-Path $Root "openai_compatible_server.py")

"""
本机 OpenAI 兼容 /v1/chat/completions，供 downAiGC 后端 REMOTE_INFERENCE_URL 指向。

GPU+CPU：通过环境变量 MAX_MEMORY_GPU / MAX_MEMORY_CPU（或 MAX_MEMORY）做分层加载；
可选 LOAD_IN_8BIT=1 在显存紧张时把更多权重压在 8GB GPU 上，通常比「半 FP16 半 CPU」解码更快。

安全：INFERENCE_API_KEY（Bearer）；可选 ALLOWED_INFERENCE_HOSTS。
"""
from __future__ import annotations

import os
import secrets
import threading
import time
from pathlib import Path
from typing import Any, Dict, List, Optional, Union

import torch
from fastapi import FastAPI, HTTPException, Request
from fastapi.responses import JSONResponse
from transformers import AutoModelForCausalLM, AutoTokenizer

# ---------- 配置（环境变量）----------
MODEL_DIR = Path(os.environ.get("MERGED_MODEL_DIR", "")).expanduser() or (
    Path(__file__).resolve().parent / "merged"
)
SERVE_HOST = os.environ.get("SERVE_HOST", "127.0.0.1").strip()
SERVE_PORT = int(os.environ.get("SERVE_PORT", "8010"))
INFERENCE_API_KEY = os.environ.get("INFERENCE_API_KEY", "").strip()
ALLOWED_HOSTS = {
    h.strip().lower()
    for h in os.environ.get("ALLOWED_INFERENCE_HOSTS", "").split(",")
    if h.strip()
}

# 混合显存：为 KV / 碎片留余量，避免 OOM（GiB 字符串见 HF accelerate 文档）
# 例：8G 卡设 6~7GiB，32G 内存设 24~28GiB 承接其余层
# 也可一条：MAX_MEMORY=0:6.5GiB,cpu:26GiB
LOAD_IN_8BIT = os.environ.get("LOAD_IN_8BIT", "").strip() in ("1", "true", "yes")
LOAD_IN_4BIT = os.environ.get("LOAD_IN_4BIT", "").strip() in ("1", "true", "yes")
# Flash / SDPA：Qwen2 在较新 transformers 上可走 sdpa，减轻显存与延迟
USE_SDPA = os.environ.get("ATTN_SDPA", "1").strip() in ("1", "true", "yes", "")
TORCH_COMPILE = os.environ.get("TORCH_COMPILE", "").strip() in ("1", "true", "yes")

_LOCK = threading.Lock()
_model: Any = None
_tokenizer: Any = None
_load_error: Optional[str] = None
_model_meta: Dict[str, Any] = {}


def _parse_max_memory() -> Optional[Dict[Union[int, str], str]]:
    """返回 accelerate 接受的 max_memory；未配置则 None（由 device_map 自行分配）。"""
    raw = os.environ.get("MAX_MEMORY", "").strip()
    if raw:
        out: Dict[Union[int, str], str] = {}
        for part in raw.split(","):
            part = part.strip()
            if ":" not in part:
                continue
            k, v = part.split(":", 1)
            k, v = k.strip(), v.strip()
            if k.isdigit():
                out[int(k)] = v
            elif k.lower() == "cpu":
                out["cpu"] = v
        return out or None
    gpu = os.environ.get("MAX_MEMORY_GPU", "").strip()
    cpu = os.environ.get("MAX_MEMORY_CPU", "").strip()
    if not gpu and not cpu:
        return None
    mm: Dict[Union[int, str], str] = {}
    if gpu:
        mm[0] = gpu
    if cpu:
        mm["cpu"] = cpu
    return mm or None


def _dtype() -> torch.dtype:
    if torch.cuda.is_available():
        if torch.cuda.is_bf16_supported():
            return torch.bfloat16
        return torch.float16
    return torch.float32


def _infer_input_device(model: Any) -> torch.device:
    """device_map 多设备时，把 input_ids 放在词嵌入所在设备。"""
    dev = getattr(model, "device", None)
    if isinstance(dev, torch.device):
        return dev
    try:
        emb = model.get_input_embeddings()
        if emb is not None and getattr(emb, "weight", None) is not None:
            return emb.weight.device
    except Exception:  # noqa: BLE001
        pass
    return next(model.parameters()).device


def _load_model() -> None:
    global _model, _tokenizer, _load_error, _model_meta
    if _model is not None:
        return
    with _LOCK:
        if _model is not None:
            return
        if not MODEL_DIR.is_dir():
            _load_error = f"模型目录不存在: {MODEL_DIR}"
            return
        try:
            tok = AutoTokenizer.from_pretrained(
                str(MODEL_DIR), trust_remote_code=True, local_files_only=True
            )
            kwargs: Dict[str, Any] = {
                "trust_remote_code": True,
                "local_files_only": True,
                "low_cpu_mem_usage": True,
            }
            max_mem = _parse_max_memory()

            if LOAD_IN_4BIT or LOAD_IN_8BIT:
                try:
                    from transformers import BitsAndBytesConfig
                except ImportError as e:
                    raise RuntimeError(
                        "LOAD_IN_8BIT/LOAD_IN_4BIT 需要安装 bitsandbytes，参见 requirements-serve.txt 注释"
                    ) from e
                bnb_kw: Dict[str, Any] = {}
                if LOAD_IN_4BIT:
                    bnb_kw["load_in_4bit"] = True
                    bnb_kw["bnb_4bit_compute_dtype"] = _dtype()
                else:
                    bnb_kw["load_in_8bit"] = True
                kwargs["quantization_config"] = BitsAndBytesConfig(**bnb_kw)
                kwargs["device_map"] = "auto"
                if max_mem:
                    kwargs["max_memory"] = max_mem
            elif torch.cuda.is_available():
                kwargs["torch_dtype"] = _dtype()
                kwargs["device_map"] = "auto"
                if max_mem:
                    kwargs["max_memory"] = max_mem
            else:
                kwargs["torch_dtype"] = torch.float32

            if USE_SDPA:
                try:
                    kwargs["attn_implementation"] = "sdpa"
                except TypeError:
                    pass

            mod = AutoModelForCausalLM.from_pretrained(str(MODEL_DIR), **kwargs)
            if not torch.cuda.is_available() and not (LOAD_IN_4BIT or LOAD_IN_8BIT):
                mod = mod.to(dtype=torch.float32)

            if TORCH_COMPILE and torch.cuda.is_available():
                try:
                    mod = torch.compile(mod, mode="reduce-overhead", fullgraph=False)  # type: ignore[assignment]
                    _model_meta["torch_compile"] = True
                except Exception as e:  # noqa: BLE001
                    _model_meta["torch_compile"] = False
                    _model_meta["torch_compile_error"] = str(e)
            else:
                _model_meta["torch_compile"] = False

            _tokenizer = tok
            _model = mod
            _load_error = None
            _model_meta.update(
                {
                    "load_in_8bit": LOAD_IN_8BIT,
                    "load_in_4bit": LOAD_IN_4BIT,
                    "max_memory": max_mem,
                    "sdpa": bool(kwargs.get("attn_implementation")),
                    "hf_device_map": getattr(mod, "hf_device_map", None),
                }
            )
        except Exception as e:  # noqa: BLE001
            _load_error = str(e)
            _model = None
            _tokenizer = None
            _model_meta = {}


app = FastAPI(title="merged-local-openai", version="1.0")


@app.on_event("startup")
def _startup() -> None:
    _load_model()


def _auth(request: Request) -> None:
    if ALLOWED_HOSTS:
        host = (request.headers.get("host") or "").split(":")[0].lower()
        if host and host not in ALLOWED_HOSTS:
            raise HTTPException(status_code=403, detail="host not allowed")
    if not INFERENCE_API_KEY:
        return
    auth = (request.headers.get("authorization") or "").strip()
    expected = f"Bearer {INFERENCE_API_KEY}"
    if not secrets.compare_digest(auth, expected):
        raise HTTPException(status_code=401, detail="Unauthorized")


@app.get("/health")
def health() -> Dict[str, Any]:
    ok = _model is not None and _tokenizer is not None
    return {
        "ok": ok,
        "model_dir": str(MODEL_DIR),
        "error": _load_error,
        "cuda": torch.cuda.is_available(),
        "meta": _model_meta,
    }


@app.post("/v1/chat/completions")
async def chat_completions(request: Request) -> JSONResponse:
    _auth(request)
    if _model is None or _tokenizer is None:
        raise HTTPException(
            status_code=503,
            detail=_load_error or "model not loaded",
        )
    try:
        body: Dict[str, Any] = await request.json()
    except Exception as e:  # noqa: BLE001
        raise HTTPException(status_code=400, detail=str(e)) from e

    messages: List[Dict[str, Any]] = body.get("messages") or []
    if not messages:
        raise HTTPException(status_code=400, detail="messages required")

    max_tokens = int(body.get("max_tokens") or 512)
    max_tokens = max(1, min(max_tokens, 8192))
    temperature = float(body.get("temperature") or 0.7)
    top_p = float(body.get("top_p") or 0.9)
    model_id = str(body.get("model") or "merged")

    try:
        prompt_ids = _tokenizer.apply_chat_template(
            messages,
            tokenize=True,
            add_generation_prompt=True,
            return_tensors="pt",
        )
    except Exception as e:  # noqa: BLE001
        raise HTTPException(status_code=400, detail=f"chat template: {e}") from e

    if isinstance(prompt_ids, dict):
        prompt_ids = prompt_ids["input_ids"]

    in_dev = _infer_input_device(_model)
    prompt_ids = prompt_ids.to(in_dev)
    pad_id = _tokenizer.pad_token_id or _tokenizer.eos_token_id

    t0 = time.perf_counter()
    with torch.inference_mode():
        out = _model.generate(
            prompt_ids,
            max_new_tokens=max_tokens,
            do_sample=temperature > 0.001,
            temperature=max(temperature, 1e-5),
            top_p=top_p,
            pad_token_id=pad_id,
            eos_token_id=_tokenizer.eos_token_id,
            use_cache=True,
        )
    new_tokens = out[0, prompt_ids.shape[-1] :]
    text = _tokenizer.decode(new_tokens, skip_special_tokens=True).strip()
    elapsed_ms = int((time.perf_counter() - t0) * 1000)

    payload = {
        "id": f"chatcmpl-local-{int(time.time() * 1000)}",
        "object": "chat.completion",
        "created": int(time.time()),
        "model": model_id,
        "choices": [
            {
                "index": 0,
                "message": {"role": "assistant", "content": text},
                "finish_reason": "stop",
            }
        ],
        "usage": {
            "prompt_tokens": int(prompt_ids.shape[-1]),
            "completion_tokens": int(new_tokens.shape[0]),
            "total_tokens": int(prompt_ids.shape[-1] + new_tokens.shape[0]),
        },
        "system_fingerprint": f"local-{elapsed_ms}ms",
    }
    return JSONResponse(content=payload)


def main() -> None:
    import uvicorn

    if not INFERENCE_API_KEY:
        print(
            "[warn] INFERENCE_API_KEY 未设置，任意客户端只要能访问到本端口即可调用。"
            "公网暴露前请务必设置强随机密钥，并在网站后端 REMOTE_INFERENCE_API_KEY 使用同一值。"
        )
    mm = _parse_max_memory()
    print(f"[serve] model_dir={MODEL_DIR} host={SERVE_HOST} port={SERVE_PORT}")
    print(
        f"[serve] load_in_8bit={LOAD_IN_8BIT} load_in_4bit={LOAD_IN_4BIT} "
        f"max_memory={mm} sdpa={USE_SDPA} torch_compile={TORCH_COMPILE}"
    )
    uvicorn.run(app, host=SERVE_HOST, port=SERVE_PORT, reload=False, workers=1)


if __name__ == "__main__":
    main()

