@'
# start-all-local-ai.ps1
# 一键拉起：本地 merged 推理 + cloudflared 隧道 + 回写 backend/.env（REMOTE_INFERENCE_*）
# 规则：大文件下载优先 aria2c（多连接、断点续传、重试），避免 pip/conda 超时。

param(
  [string]$BackendEnvPath = "..\backend\.env",
  [string]$ModelDir = ".\merged",
  [string]$ServeHost = "127.0.0.1",
  [int]$ServePort = 8010,
  [switch]$UseHybrid8G32G,
  [switch]$RestartBackend
)

$ErrorActionPreference = "Stop"
$Root = Split-Path -Parent $MyInvocation.MyCommand.Path
Set-Location $Root

$Py = Join-Path $Root ".venv-serve\Scripts\python.exe"
if (-not (Test-Path $Py)) {
  throw "未找到 .venv-serve，请先创建并安装依赖。"
}
if (-not (Test-Path $ModelDir)) {
  throw "模型目录不存在: $ModelDir"
}

function Upsert-EnvLine([string]$Path, [string]$Key, [string]$Value) {
  $content = if (Test-Path $Path) { Get-Content $Path -Raw -Encoding UTF8 } else { "" }
  $pattern = "(?m)^" + [regex]::Escape($Key) + "=.*$"
  $line = "$Key=$Value"
  if ([regex]::IsMatch($content, $pattern)) {
    $content = [regex]::Replace($content, $pattern, $line)
  } else {
    if ($content.Length -gt 0 -and -not $content.EndsWith("`n")) { $content += "`n" }
    $content += "$line`n"
  }
  Set-Content -Path $Path -Value $content -Encoding UTF8
}

function Ensure-CudaTorch {
  $info = & $Py -c "import torch;print(torch.__version__);print(torch.cuda.is_available());print(torch.version.cuda)" 2>$null
  if ($LASTEXITCODE -eq 0 -and $info -and ($info -join "`n") -match "True") {
    Write-Host "[ok] CUDA torch 已可用" -ForegroundColor Green
    return
  }

  $wheelName = "torch-2.11.0+cu128-cp313-cp313-win_amd64.whl"
  $wheelPath = Join-Path $Root $wheelName
  $wheelUrl = "https://download.pytorch.org/whl/cu128/torch-2.11.0%2Bcu128-cp313-cp313-win_amd64.whl"

  if (-not (Test-Path $wheelPath)) {
    $aria2 = Get-Command aria2c -ErrorAction SilentlyContinue
    if (-not $aria2) {
      throw "未找到 aria2c。请先安装 aria2，或手动下载 $wheelUrl 到 $wheelPath"
    }
    Write-Host "[rule] 使用 aria2c 下载大文件（多连接+断点续传+重试）" -ForegroundColor Cyan
    & $aria2.Source --file-allocation=none --continue=true --max-connection-per-server=16 --split=16 --min-split-size=1M --timeout=60 --max-tries=0 --retry-wait=2 --dir "$Root" --out "$wheelName" "$wheelUrl"
    if ($LASTEXITCODE -ne 0) { throw "aria2c 下载 torch wheel 失败" }
  }

  & $Py -m pip install "$wheelPath"
  if ($LASTEXITCODE -ne 0) { throw "安装 CUDA torch 失败" }

  $verify = & $Py -c "import torch;print(torch.__version__);print(torch.cuda.is_available());print(torch.version.cuda)"
  if (($verify -join "`n") -notmatch "True") {
    throw "CUDA torch 校验失败：`n$($verify -join "`n")"
  }
}

Ensure-CudaTorch

# 停掉旧的 local-ai 进程（只杀 openai_compatible_server.py）
Get-CimInstance Win32_Process |
  Where-Object { $_.Name -eq "python.exe" -and $_.CommandLine -like "*openai_compatible_server.py*" } |
  ForEach-Object { Stop-Process -Id $_.ProcessId -Force }

# 生成随机 key（每次刷新，提升安全）
$NewKey = & $Py -c "import secrets; print(secrets.token_urlsafe(40))"

$ServeLog = Join-Path $Root ".run-serve.log"
$TunnelLog = Join-Path $Root ".run-tunnel.log"

if (Test-Path $ServeLog) { Remove-Item $ServeLog -Force }
if (Test-Path $TunnelLog) { Remove-Item $TunnelLog -Force }

$serveCmd = @(
  "`$env:INFERENCE_API_KEY='$NewKey'",
  "`$env:MERGED_MODEL_DIR='$((Resolve-Path $ModelDir).Path)'",
  "`$env:SERVE_HOST='$ServeHost'",
  "`$env:SERVE_PORT='$ServePort'"
)
if ($UseHybrid8G32G) {
  $serveCmd += "`$env:HYBRID_PRESET='8g32g'"
} else {
  $serveCmd += "Remove-Item Env:HYBRID_PRESET -ErrorAction SilentlyContinue"
}
$serveCmd += "Set-Location '$Root'"
$serveCmd += "& '$Py' '.\openai_compatible_server.py'"

Start-Process -FilePath "powershell" -ArgumentList @(
  "-NoProfile", "-ExecutionPolicy", "Bypass", "-Command", ($serveCmd -join "; ")
) -WindowStyle Hidden -RedirectStandardOutput $ServeLog -RedirectStandardError $ServeLog | Out-Null

# 等待健康
$localHealth = "http://$ServeHost`:$ServePort/health"
$ok = $false
for ($i = 0; $i -lt 90; $i++) {
  Start-Sleep -Seconds 2
  try {
    $h = Invoke-RestMethod -Uri $localHealth -TimeoutSec 8
    if ($h.ok -eq $true) { $ok = $true; break }
  } catch {}
}
if (-not $ok) {
  throw "本地推理未就绪，查看日志: $ServeLog"
}

# 启动 cloudflared 隧道
$cf = Get-Command cloudflared -ErrorAction SilentlyContinue
if (-not $cf) { throw "未找到 cloudflared" }
Start-Process -FilePath $cf.Source -ArgumentList @("tunnel", "--url", "http://$ServeHost`:$ServePort", "--protocol", "http2") -WindowStyle Hidden -RedirectStandardOutput $TunnelLog -RedirectStandardError $TunnelLog | Out-Null

# 解析 trycloudflare 域名
$tunnelUrl = $null
for ($i = 0; $i -lt 60; $i++) {
  Start-Sleep -Seconds 1
