def _collapse_reference_paragraphs(parts: List[str]) -> List[str]:
    """
    从首个以「参考文献」开头的段落起合并到列表末尾，使参考文献在 UI 中只占一个对比框。
    空段落会剔除；合并段之间用双换行拼接，以贴近常见排版。
    """
    if not parts:
        return parts
    idx = -1
    for i, p in enumerate(parts):
