import React from "react";
import { App, Card, Space, Typography, Alert } from "antd";
import { GiftOutlined, BulbOutlined, PlayCircleOutlined } from "@ant-design/icons";
import GalaxyButton from "../components/GalaxyButton";
import AdPlayerModal from "../components/AdPlayerModal";
import { WATCH_AD_REWARD_ITEM } from "../components/AdCarousel";
import { useReward } from "../state/RewardContext";
import { apiRequest } from "../api/client";
import { getTodayKey } from "../state/rewardState";

/** 顶栏「积分 +」进入：本地示意积分 + 看广告领积分（原概览轮播逻辑） */
const WalletPointsPage: React.FC = () => {
  const { message } = App.useApp();
  const { state, addPoints, canSignInToday, syncFromServer } = useReward();
  const [adOpen, setAdOpen] = React.useState(false);

  const onServerSignIn = () => {
    (async () => {
      const res = await apiRequest<{
        gained: number;
        streak: number;
        points: number;
      }>("/api/points/signin", { method: "POST" });

      syncFromServer({
        ...state,
        points: res.points,
        signIn: {
          lastDate: getTodayKey(),
          streak: res.streak
        }
      });

      message.success(`签到成功：+${res.gained} 积分（连签 ${res.streak} 天）`);
    })().catch(() => {
      // apiRequest 内部会处理 401 跳转登录
    });
  };

  return (
    <Space direction="vertical" size={16} style={{ width: "100%", maxWidth: 720 }}>
      <AdPlayerModal open={adOpen} ad={adOpen ? WATCH_AD_REWARD_ITEM : null} onClose={() => setAdOpen(false)} />

      <div className="console-stagger-item console-stagger-item--1">
        <Card>
          <Space direction="vertical" size={12} style={{ width: "100%" }}>
            <Typography.Title level={4} style={{ margin: 0 }}>
              <GiftOutlined style={{ marginRight: 10, color: "#6366f1" }} />
              我的积分
            </Typography.Title>
            <Typography.Text type="secondary">演示用积分，仅存本机，可用于后续权益示意。</Typography.Text>
            <div>
              <Typography.Text type="secondary">当前积分</Typography.Text>
              <Typography.Title level={2} style={{ margin: "4px 0 0", fontVariantNumeric: "tabular-nums" }}>
                {state.points}
              </Typography.Title>
            </div>
            {state.signIn.streak > 0 ? (
              <Typography.Text type="secondary">连签天数：{state.signIn.streak}</Typography.Text>
            ) : null}
          </Space>
        </Card>
      </div>

      <div className="console-stagger-item console-stagger-item--2">
        <Card title="获取积分">
          <Space direction="vertical" size={14} style={{ width: "100%" }}>
            <Typography.Paragraph style={{ marginBottom: 0 }}>
              看广告完整观看可获得积分；也可通过下方示意按钮或每日签到（服务端）领取。
            </Typography.Paragraph>
            <GalaxyButton
              block
              icon={<PlayCircleOutlined />}
              onClick={() => setAdOpen(true)}
              style={{ maxWidth: 360 }}
            >
              看广告获取积分（完整观看可得 {WATCH_AD_REWARD_ITEM.points} 积分）
            </GalaxyButton>
            <Space wrap>
              <GalaxyButton onClick={() => addPoints(10)}>+10 积分</GalaxyButton>
              <GalaxyButton onClick={() => addPoints(30)}>+30 积分</GalaxyButton>
              <GalaxyButton disabled={!canSignInToday} onClick={onServerSignIn}>
                {canSignInToday ? "今日签到领积分" : "今日已签到"}
              </GalaxyButton>
            </Space>
          </Space>
        </Card>
      </div>

      <div className="console-stagger-item console-stagger-item--3">
        <Alert
          type="info"
          showIcon
          icon={<BulbOutlined />}
          message="提示"
          description="正式产品可在此展示任务中心、邀请奖励、兑换商城等模块。概览轮播仅保留可跳转的推广位。"
        />
      </div>
    </Space>
  );
};

export default WalletPointsPage;

