import React from "react";
import { Card, Space, Typography, Row, Col, Tag } from "antd";
import { useNavigate } from "react-router-dom";
import AdCarousel, { type AdItem } from "../components/AdCarousel";
import GalaxyButton from "../components/GalaxyButton";

/** 展示用：两位小数 + tabular-nums */
const y = (n: number) =>
  n.toLocaleString("zh-CN", { minimumFractionDigits: 2, maximumFractionDigits: 2 });

type MemberPlanRow = {
  key: string;
  title: string;
  tag: string;
  tagColor?: string;
  total: number;
  /** 展示用日均（元），与表格一致；永久档为估算文案 */
  dailyDisplay: string;
  hook: string;
  /** 永久 / 长周期可走咨询，其余走控制台示意开通 */
  navigateTo: "/console/polish" | "/console/feedback";
};

const MEMBER_PLANS: MemberPlanRow[] = [
  {
    key: "d1",
    title: "单日体验卡",
    tag: "1 天",
    total: 5.99,
    dailyDisplay: "5.99",
    hook: "6 块不到，随便付，试用零压力",
    navigateTo: "/console/polish"
  },
  {
    key: "w7",
    title: "7 天周卡",
    tag: "7 天",
    tagColor: "cyan",
    total: 39.9,
    dailyDisplay: "5.70",
    hook: "不到 40 块，短期用超划算",
    navigateTo: "/console/polish"
  },
  {
    key: "m30",
    title: "30 天月卡",
    tag: "30 天",
    tagColor: "blue",
    total: 149.9,
    dailyDisplay: "4.99",
    hook: "不到 150，学生完全无负担",
    navigateTo: "/console/polish"
  },
  {
    key: "q90",
    title: "90 天季卡",
    tag: "90 天",
    tagColor: "geekblue",
    total: 399.9,
    dailyDisplay: "4.44",
    hook: "不到 400，稳定使用性价比拉满",
    navigateTo: "/console/polish"
  },
  {
    key: "h180",
    title: "半年（180 天）",
    tag: "180 天",
    tagColor: "purple",
    total: 729.9,
    dailyDisplay: "4.06",
    hook: "日均仅 4 块出头，接近成本价",
    navigateTo: "/console/polish"
  },
  {
    key: "y365",
    title: "一年（365 天）",
    tag: "365 天",
    tagColor: "gold",
    total: 1459.9,
    dailyDisplay: "4.00",
    hook: "保本底价，年度最省",
    navigateTo: "/console/polish"
  },
  {
    key: "y730",
    title: "两年（730 天）",
    tag: "730 天",
    tagColor: "orange",
    total: 2919.9,
    dailyDisplay: "4.00",
    hook: "两年均价，锁死超低价",
    navigateTo: "/console/feedback"
  },
  {
    key: "life",
    title: "永久会员",
    tag: "终身",
    tagColor: "magenta",
    total: 5999.99,
    dailyDisplay: "≈4.10",
    hook: "终身不限时，一劳永逸",
    navigateTo: "/console/feedback"
  }
];

const DashboardPage: React.FC = () => {
  const navigate = useNavigate();

  return (
    <Space direction="vertical" size={16} style={{ width: "100%" }}>
      <div className="console-stagger-item console-stagger-item--1">
        <AdCarousel
          onClickAd={(ad: AdItem) => {
            if (ad.navigateTo) navigate(ad.navigateTo);
          }}
        />
      </div>

      <div className="console-stagger-item console-stagger-item--2">
        <Typography.Title level={5} style={{ margin: "0 0 4px" }}>
          会员中心
