import React from "react";
import { App, Modal, Spin, Typography, Button, Space } from "antd";
import * as QRCode from "qrcode";
import { apiRequest } from "../api/client";
import { useReward } from "../state/RewardContext";

type TicketCreateRes = { ticketId: string; watchUrl: string; expiresAt: string };
type TicketStatusRes = { status: string; points?: number | null };
type PointsMeRes = {
  points: number;
  signIn: { lastDate?: string | null; streak?: number };
};

type AdWatchQrModalProps = {
  open: boolean;
  onClose: () => void;
};

const POLL_MS = 2500;

const AdWatchQrModal: React.FC<AdWatchQrModalProps> = ({ open, onClose }) => {
  const { message } = App.useApp();
  const { state, syncFromServer } = useReward();
  const stateRef = React.useRef(state);
  stateRef.current = state;

  const [loading, setLoading] = React.useState(false);
  const [errorText, setErrorText] = React.useState("");
  const [qrDataUrl, setQrDataUrl] = React.useState("");
  const [ticketId, setTicketId] = React.useState("");
  const [statusLabel, setStatusLabel] = React.useState("");
  const pollRef = React.useRef<number | null>(null);

  const clearPoll = React.useCallback(() => {
    if (pollRef.current != null) {
      window.clearInterval(pollRef.current);
      pollRef.current = null;
    }
  }, []);

  const refreshPointsFromServer = React.useCallback(async () => {
    const me = await apiRequest<PointsMeRes>("/api/points/me");
    const s = stateRef.current;
    syncFromServer({
      ...s,
      points: me.points,
      signIn: {
        lastDate: me.signIn?.lastDate ?? null,
        streak: typeof me.signIn?.streak === "number" ? me.signIn.streak : s.signIn.streak
      }
    });
  }, [syncFromServer]);

  React.useEffect(() => {
    if (!open) {
      clearPoll();
      setLoading(false);
      setErrorText("");
      setQrDataUrl("");
      setTicketId("");
      setStatusLabel("");
      return;
    }

    let cancelled = false;
    (async () => {
      setLoading(true);
      setErrorText("");
      setQrDataUrl("");
      setTicketId("");
      setStatusLabel("pending");
      clearPoll();
      try {
        const res = await apiRequest<TicketCreateRes>("/api/ad/watch-tickets", { method: "POST" });
        if (cancelled) return;
        setTicketId(res.ticketId);
        const dataUrl = await QRCode.toDataURL(res.watchUrl, { width: 220, margin: 2 });
        if (cancelled) return;
        setQrDataUrl(dataUrl);
      } catch (e: unknown) {
        if (cancelled) return;
        const detail = typeof e === "object" && e && "detail" in e ? String((e as { detail?: string }).detail) : "";
        setErrorText(detail || "无法创建看广告票据，请检查网络或登录状态");
        setStatusLabel("");
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();

    return () => {
      cancelled = true;
      clearPoll();
    };
  }, [open, clearPoll]);

  React.useEffect(() => {
    if (!open || !ticketId || loading || errorText) {
      return;
    }

    const tick = async () => {
      try {
        const st = await apiRequest<TicketStatusRes>(`/api/ad/watch-tickets/${encodeURIComponent(ticketId)}`);
        setStatusLabel(st.status);
        if (st.status === "completed") {
          clearPoll();
          await refreshPointsFromServer();
          message.success(
            typeof st.points === "number" ? `领取成功，当前积分 ${st.points}` : "领取成功"
          );
        } else if (st.status === "expired") {
          clearPoll();
          message.warning("二维码已过期，请关闭后重新点击「领积分」");
        }
      } catch {
        // 轮询失败不打断，下次再试
      }
    };

    pollRef.current = window.setInterval(() => {
      void tick();
    }, POLL_MS);
    void tick();

    return () => clearPoll();
  }, [open, ticketId, loading, errorText, clearPoll, message, refreshPointsFromServer]);

  return (
    <Modal
      open={open}
      title="微信扫码看广告领积分"
      onCancel={onClose}
      footer={
        <Button type="primary" onClick={onClose}>
          关闭
        </Button>
      }
      destroyOnClose
      width={400}
    >
      <Space direction="vertical" size={14} style={{ width: "100%" }}>
        <Typography.Paragraph style={{ marginBottom: 0 }} className="ad-watch-qr-modal__hint">
          请使用<strong>微信扫一扫</strong>识别下方二维码，在打开的页面中<strong>保持约 30 秒</strong>直至提示领取成功；完成后本页积分将自动刷新。
        </Typography.Paragraph>
        {loading ? (
          <div style={{ textAlign: "center", padding: "32px 0" }}>
            <Spin tip="正在生成二维码…" />
          </div>
        ) : errorText ? (
          <Typography.Text type="danger">{errorText}</Typography.Text>
        ) : qrDataUrl ? (
          <div className="ad-watch-qr-modal__qr-wrap">
            <img src={qrDataUrl} alt="微信扫码打开看广告页" width={220} height={220} />
            {statusLabel ? (
              <Typography.Text type="secondary" className="ad-watch-qr-modal__status">
                状态：{statusLabel === "pending" ? "等待扫码并完成观看" : statusLabel}
              </Typography.Text>
            ) : null}
          </div>
        ) : null}
      </Space>
    </Modal>
  );
};

