      dataIndex: "createdAt",
      key: "createdAt",
      width: 168,
      render: (v: string) => (v ? new Date(v).toLocaleString() : "-")
    },
    {
      title: "积分",
      dataIndex: "points",
      key: "points",
      width: 88,
      render: (v: number) => v.toLocaleString()
    },
    {
      title: "看广完成",
      dataIndex: "adViews",
      key: "adViews",
      width: 100,
      render: (v: number) => v.toLocaleString()
    },
    {
      title: "字数用量",
      key: "quota",
      width: 160,
      render: (_: unknown, row: OverviewResponse["users"][number]) =>
        `${row.wordsUsed.toLocaleString()} / ${row.wordsQuota.toLocaleString()}`
    },
    {
      title: "剩余额度",
      dataIndex: "remainingQuota",
      key: "remainingQuota",
      width: 108,
      render: (v: number) => v.toLocaleString()
    },
    {
      title: "月活",
      key: "monthlyActive",
      width: 88,
      render: (_: unknown, row: OverviewResponse["users"][number]) =>
        row.monthlyActive ? <Tag color="success">活跃</Tag> : <Tag>未活跃</Tag>
    },
    {
      title: "账号状态",
      key: "isBanned",
      width: 96,
      render: (_: unknown, row: OverviewResponse["users"][number]) =>
        row.isBanned ? <Tag color="error">已封禁</Tag> : <Tag color="success">正常</Tag>
    },
    {
      title: "操作",
      key: "actions",
      width: 200,
      fixed: "right" as const,
      render: (_: unknown, row: OverviewResponse["users"][number]) => (
        <Space size={8}>
          <Popconfirm
            title={row.isBanned ? "确认解封此账号？" : "确认封禁此账号？"}
            onConfirm={() => {
              toggleBan(row).catch((e: { detail?: string }) => message.error(e?.detail || "操作失败，请重试"));
            }}
          >
            <Button size="small">{row.isBanned ? "解封" : "封号"}</Button>
          </Popconfirm>
          <Popconfirm
            title="确认删除此账号？该操作不可恢复"
            okButtonProps={{ danger: true }}
            onConfirm={() => {
              removeUser(row).catch((e: { detail?: string }) =>
                message.error(e?.detail || "删除失败，请重试")
              );
            }}
          >
            <Button size="small" danger>
              删除
            </Button>
          </Popconfirm>
        </Space>
      )
    }
  ];

  return (
    <Space direction="vertical" size={16} style={{ width: "100%" }}>
      <div className="console-stagger-item console-stagger-item--1">
        <Row justify="space-between" align="middle" style={{ marginBottom: 4 }}>
          <Col>
            <Typography.Title level={4} style={{ margin: 0 }}>
              管理概览
            </Typography.Title>
            <Typography.Text type="secondary" style={{ fontSize: 13 }}>
              看广次数来自已完成扫码广告票据；月活含近 30 天内有任务或完成看广的用户。
            </Typography.Text>
          </Col>
          <Col>
            <Button icon={<ReloadOutlined />} onClick={() => reload()} loading={loading}>
              刷新数据
            </Button>
          </Col>
        </Row>
        <Row gutter={[12, 12]}>
          <Col xs={24} sm={12} lg={8}>
            <Card>
              <Statistic title="用户总数" value={data?.userCount ?? 0} />
            </Card>
          </Col>
          <Col xs={24} sm={12} lg={8}>
            <Card>
              <Statistic title="月活用户数" value={data?.monthlyActiveUsers ?? 0} />
