            </Card>
          </Col>
          <Col xs={24} sm={12} lg={8}>
            <Card>
              <Statistic
                title="字数额度使用率"
                value={
                  data?.totalWordsQuota
                    ? Number(((data.usedWordsQuota / data.totalWordsQuota) * 100).toFixed(2))
