          </Col>
          <Col xs={24} sm={12} lg={8}>
            <Card>
              <Statistic title="任务总数" value={data?.totalTasksCount ?? 0} />
            </Card>
          </Col>
        </Row>
      </div>

      <div className="console-stagger-item console-stagger-item--2">
        <Row gutter={[12, 12]}>
          <Col xs={24} lg={8}>
            <Card>
              <SimpleLineChart
                title="近30天活跃用户数（按日）"
                data={(data?.dailyMetrics ?? []).map((d) => ({
                  label: d.date,
                  value: d.activeUsers
                }))}
              />
            </Card>
          </Col>
          <Col xs={24} lg={8}>
            <Card>
              <SimpleLineChart
                title="近30天看广完成次数（按日）"
                stroke="#8b5cf6"
                data={(data?.dailyMetrics ?? []).map((d) => ({
                  label: d.date,
                  value: d.adViews
                }))}
              />
            </Card>
          </Col>
          <Col xs={24} lg={8}>
            <Card>
              <SimpleLineChart
                title="近30天润色字数（按日）"
                stroke="#059669"
                data={(data?.dailyMetrics ?? []).map((d) => ({
                  label: d.date,
                  value: d.wordsUsed
                }))}
              />
            </Card>
          </Col>
        </Row>
      </div>

      <div className="console-stagger-item console-stagger-item--3">
