export type RewardState = {
  points: number;
  /** 账户余额（元），本地示意，非真实支付 */
  balanceYuan: number;
  signIn: {
    lastDate: string | null; // YYYY-MM-DD
    streak: number;
  };
};

/** 旧版单桶 key，首次按用户读取时迁移到 per-user key */
const LEGACY_STORAGE_KEY = "paper-polish.rewardState.v1";

export function rewardStorageKey(userId: string | null): string {
  if (!userId) return `${LEGACY_STORAGE_KEY}.__guest__`;
  return `${LEGACY_STORAGE_KEY}.u.${userId}`;
}

export function getTodayKey(d = new Date()): string {
  const yyyy = d.getFullYear();
  const mm = String(d.getMonth() + 1).padStart(2, "0");
  const dd = String(d.getDate()).padStart(2, "0");
  return `${yyyy}-${mm}-${dd}`;
}

export function loadRewardState(userId: string | null): RewardState {
  const key = rewardStorageKey(userId);
  let raw = (() => {
    try {
      return localStorage.getItem(key);
    } catch {
      return null;
    }
  })();

  if (!raw && userId) {
    try {
      raw = localStorage.getItem(LEGACY_STORAGE_KEY);
      if (raw) {
        localStorage.setItem(key, raw);
      }
    } catch {
      // ignore
    }
  }

  const empty = (): RewardState => ({
    points: 0,
    balanceYuan: 0,
    signIn: { lastDate: null, streak: 0 }
  });

  if (!raw) {
    return empty();
  }
  try {
    const parsed = JSON.parse(raw) as RewardState;
    if (typeof parsed?.points !== "number" || typeof parsed?.signIn?.streak !== "number") {
      return empty();
    }
    return {
      points: parsed.points,
      balanceYuan: typeof parsed.balanceYuan === "number" ? parsed.balanceYuan : 0,
      signIn: {
        lastDate: parsed.signIn.lastDate ?? null,
        streak: parsed.signIn.streak
      }
    };
  } catch {
    return empty();
  }
}

export function saveRewardState(state: RewardState, userId: string | null) {
  try {
    localStorage.setItem(rewardStorageKey(userId), JSON.stringify(state));
  } catch {
    // ignore
  }
}

export function computeSignInReward(streak: number): number {
  return Math.min(30, 10 + Math.max(0, streak - 1) * 2);
}

import React from "react";
import {
  RewardState,
  loadRewardState,
  saveRewardState,
  getTodayKey,
  computeSignInReward
} from "./rewardState";
import { apiRequest, AUTH_CHANGED_EVENT, getAccessToken } from "../api/client";

type AuthMe = { id: string; email: string; nickname?: string | null };
type PointsMe = {
  points: number;
  signIn: { lastDate?: string | null; streak?: number };
};

type RewardContextValue = {
  state: RewardState;
  addPoints: (delta: number) => void;
  addBalanceYuan: (delta: number) => void;
  canSignInToday: boolean;
  signInToday: () => { gained: number; streak: number } | null;
  syncFromServer: (next: RewardState) => void;
};

const RewardContext = React.createContext<RewardContextValue | null>(null);

export function RewardProvider({ children }: { children: React.React.ReactNode }) {
  const [state, setState] = React.useState<RewardState>(() => loadRewardState(null));
  /** null = 访客桶；有 token 时为当前用户 id，用于分账号持久化 */
  const [persistUserId, setPersistUserId] = React.useState<string | null>(null);
  const [persistReady, setPersistReady] = React.useState(false);

  const runBootstrap = React.useCallback(async () => {
    const token = getAccessToken();
    if (!token) {
      setPersistUserId(null);
      setState(loadRewardState(null));
      return;
    }
    try {
      const me = await apiRequest<AuthMe>("/api/auth/me");
      const local = loadRewardState(me.id);
      setPersistUserId(me.id);
      try {
        const pts = await apiRequest<PointsMe>("/api/points/me");
        setState({
          ...local,
          points: pts.points,
          signIn: {
            lastDate: pts.signIn?.lastDate ?? null,
            streak: typeof pts.signIn?.streak === "number" ? pts.signIn.streak : local.signIn.streak
          }
        });
      } catch {
        setState(local);
      }
    } catch {
      setPersistUserId(null);
      setState(loadRewardState(null));
    }
  }, []);

  React.useEffect(() => {
    let cancelled = false;
    (async () => {
      setPersistReady(false);
      await runBootstrap();
      if (!cancelled) setPersistReady(true);
    })();
    const onAuth = () => {
      void (async () => {
        setPersistReady(false);
        await runBootstrap();
        if (!cancelled) setPersistReady(true);
      })();
    };
    window.addEventListener(AUTH_CHANGED_EVENT, onAuth);
    return () => {
      cancelled = true;
      window.removeEventListener(AUTH_CHANGED_EVENT, onAuth);
    };
  }, [runBootstrap]);

  React.useEffect(() => {
    if (!persistReady) return;
    saveRewardState(state, persistUserId);
  }, [state, persistUserId, persistReady]);

  const today = getTodayKey();
  const canSignInToday = state.signIn.lastDate !== today;

  const addPoints = React.useCallback((delta: number) => {
    setState((s) => ({ ...s, points: Math.max(0, s.points + delta) }));
  }, []);

  const addBalanceYuan = React.useCallback((delta: number) => {
    setState((s) => ({
      ...s,
      balanceYuan: Math.max(0, Math.round((s.balanceYuan + delta) * 100) / 100)
    }));
  }, []);

  const signInToday = React.useCallback(() => {
    if (!canSignInToday) return null;

    const last = state.signIn.lastDate;
    const yesterdayKey = getTodayKey(new Date(Date.now() - 24 * 60 * 60 * 1000));
    const nextStreak = last === yesterdayKey ? state.signIn.streak + 1 : 1;
    const gained = computeSignInReward(nextStreak);

    setState((s) => ({
      ...s,
      points: s.points + gained,
      signIn: { lastDate: today, streak: nextStreak }
    }));

    return { gained, streak: nextStreak };
  }, [canSignInToday, state.signIn.lastDate, state.signIn.streak, today]);

  const syncFromServer = React.useCallback((next: RewardState) => {
    setState(next);
  }, []);

  return (
    <RewardContext.Provider
      value={{
        state,
        addPoints,
        addBalanceYuan,
        canSignInToday,
        signInToday,
        syncFromServer
      }}
    >
      {children}
    </RewardContext.Provider>
  );
}

export function useReward() {
  const ctx = React.useContext(RewardContext);
  if (!ctx) {
    throw new Error("useReward must be used within RewardProvider");
  }
  return ctx;
}

