    if not ok:
        return RedeemUseResponse(ok=False, reason=reason, points=None, balanceYuan=None)
    return RedeemUseResponse(
        ok=True,
        reason=reason,
        points=int(extra.get("points", 0)),
        balanceYuan=float(extra.get("balanceYuan", 0.0)),
    )


