import { ReloadOutlined } from "@ant-design/icons";
import { apiRequest } from "../../api/client";

type RedeemRow = {
  id: string;
  code: string;
  rewardKind: "points" | "balance_yuan";
  amountPoints: number | null;
  amountBalanceYuan: number | null;
  scope: "all" | "single";
  restrictUserId: string | null;
  restrictEmail: string | null;
  maxUses: number;
  useCount: number;
  expiresAt: string | null;
  createdAt: string;
  disabled: boolean;
};

type FormValues = {
  rewardKind: "points" | "balance_yuan";
  amount: number;
  scope: "all" | "single";
  restrictEmail?: string;
  maxUses: number;
  expiresAt?: Dayjs | null;
  quantity: number;
};

const REASON_LABEL: Record<string, string> = {
  invalid_code: "兑换码无效",
  disabled: "兑换码已停用",
  expired: "兑换码已过期",
  depleted: "兑换次数已用尽",
  not_eligible: "该码仅限指定账号使用",
  already_used: "您已使用过该码",
  banned: "账号已封禁，无法兑换"
};

const AdminRedeemCodesPage: React.FC = () => {
  const { message } = App.useApp();
  const [form] = Form.useForm<FormValues>();
  const [rows, setRows] = React.useState<RedeemRow[]>([]);
  const [loading, setLoading] = React.useState(false);
  const [submitting, setSubmitting] = React.useState(false);
  const scope = Form.useWatch("scope", form);

  const loadRows = React.useCallback(() => {
    setLoading(true);
    apiRequest<RedeemRow[]>("/api/admin/redeem-codes", { method: "GET" })
      .then(setRows)
      .catch((e: { detail?: string }) =>
        message.error(e?.detail === "Admin access denied" ? "无管理员权限" : "加载兑换码失败")
      )
      .finally(() => setLoading(false));
  }, [message]);

  React.useEffect(() => {
    loadRows();
  }, [loadRows]);

  const onCreate = async (v: FormValues) => {
    setSubmitting(true);
    try {
      const payload: Record<string, unknown> = {
        rewardKind: v.rewardKind,
        amount: v.amount,
        scope: v.scope,
        maxUses: v.maxUses,
        quantity: v.quantity
      };
      if (v.scope === "single") {
        const em = (v.restrictEmail || "").trim();
        if (!em) {
          message.warning("指定用户时请填写用户邮箱");
          return;
        }
        payload.restrictEmail = em.toLowerCase();
      }
      if (v.expiresAt) {
        payload.expiresAt = v.expiresAt.toISOString();
      }
      const res = await apiRequest<{ codes: RedeemRow[] }>("/api/admin/redeem-codes", {
        method: "POST",
        json: payload
      });
      message.success(`已生成 ${res.codes?.length ?? 0} 个兑换码`);
      form.resetFields();
      form.setFieldsValue({
        rewardKind: "points",
        scope: "all",
        maxUses: 1,
        quantity: 1
      });
      loadRows();
    } catch (e: unknown) {
      const d = typeof e === "object" && e && "detail" in e ? String((e as { detail?: string }).detail) : "";
      message.error(d || "生成失败");
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <Space direction="vertical" size={16} style={{ width: "100%" }}>
      <div className="console-stagger-item console-stagger-item--1">
        <Typography.Title level={4} style={{ margin: 0 }}>
          兑换码生成
        </Typography.Title>
        <Typography.Text type="secondary" style={{ fontSize: 13 }}>
          积分类型写入服务端积分；金币类型增加账户余额（与顶栏「¥」一致）。全站码需设置总可兑换次数；单用户码默认每人仅可用一次。
        </Typography.Text>
      </div>

      <div className="console-stagger-item console-stagger-item--2">
        <Card title="生成新码">
          <Form<FormValues>
            form={form}
            layout="vertical"
            initialValues={{
              rewardKind: "points",
              scope: "all",
              maxUses: 1,
              quantity: 1,
              amount: 100
            }}
            onFinish={onCreate}
          >
            <Form.Item name="rewardKind" label="类型" rules={[{ required: true }]}>
              <Radio.Group
                optionType="button"
                options={[
                  { value: "points", label: "积分" },
                  { value: "balance_yuan", label: "金币（元）" }
                ]}
              />
            </Form.Item>
            <Form.Item
              noStyle
              shouldUpdate={(p, c) => p.rewardKind !== c.rewardKind}
            >
              {() => {
                const rk = form.getFieldValue("rewardKind") as FormValues["rewardKind"];
                return rk === "balance_yuan" ? (
                  <Form.Item
                    name="amount"
                    label="金币数量（元）"
                    rules={[{ required: true, type: "number", min: 0.01, max: 1_000_000 }]}
                  >
                    <InputNumber style={{ width: "100%", maxWidth: 280 }} min={0.01} step={0.01} precision={2} />
                  </Form.Item>
                ) : (
                  <Form.Item
                    name="amount"
                    label="积分数量"
                    rules={[{ required: true, type: "number", min: 1, max: 10_000_000 }]}
                  >
                    <InputNumber style={{ width: "100%", maxWidth: 280 }} min={1} step={1} precision={0} />
                  </Form.Item>
                );
              }}
            </Form.Item>
            <Form.Item name="scope" label="适用范围" rules={[{ required: true }]}>
              <Radio.Group
                optionType="button"
                options={[
                  { value: "all", label: "全部用户" },
                  { value: "single", label: "单个用户（填邮箱）" }
                ]}
              />
            </Form.Item>
            {scope === "single" ? (
              <Form.Item
                name="restrictEmail"
                label="用户邮箱"
                rules={[{ required: true, type: "email", message: "请输入有效邮箱" }]}
              >
                <Input placeholder="已注册用户的邮箱" style={{ maxWidth: 400 }} />
              </Form.Item>
            ) : null}
            <Form.Item name="maxUses" label="总可兑换次数" rules={[{ required: true, type: "number", min: 1 }]}>
              <InputNumber style={{ width: "100%", maxWidth: 280 }} min={1} max={10_000_000} />
            </Form.Item>
            <Form.Item name="quantity" label="一次生成条数" rules={[{ required: true, type: "number", min: 1 }]}>
              <InputNumber style={{ width: "100%", maxWidth: 280 }} min={1} max={100} />
            </Form.Item>
            <Form.Item name="expiresAt" label="过期时间（可选）">
              <DatePicker showTime style={{ width: "100%", maxWidth: 320 }} />
            </Form.Item>
            <Form.Item>
              <Button type="primary" htmlType="submit" loading={submitting}>
                生成
              </Button>
            </Form.Item>
          </Form>
        </Card>
      </div>

      <div className="console-stagger-item console-stagger-item--3">
        <Card
          title="已生成兑换码"
          extra={
            <Button icon={<ReloadOutlined />} onClick={() => loadRows()} loading={loading}>
              刷新
            </Button>
          }
        >
          <Table<RedeemRow>
            rowKey="id"
            loading={loading}
            dataSource={rows}
            pagination={{ pageSize: 12, showSizeChanger: true }}
            scroll={{ x: 1100 }}
            columns={[
              {
                title: "兑换码",
                dataIndex: "code",
                width: 160,
                render: (c: string) => (
                  <Typography.Text copyable code>
                    {c}
                  </Typography.Text>
                )
              },
              {
                title: "类型",
                dataIndex: "rewardKind",
                width: 100,
                render: (k: string) =>
                  k === "balance_yuan" ? <Tag color="gold">金币</Tag> : <Tag color="blue">积分</Tag>
              },
              {
                title: "面额",
                key: "amt",
                width: 120,
                render: (_: unknown, r: RedeemRow) =>
                  r.rewardKind === "points"
                    ? `${(r.amountPoints ?? 0).toLocaleString()} 分`
                    : `¥ ${(r.amountBalanceYuan ?? 0).toLocaleString("zh-CN", { minimumFractionDigits: 2 })}`
              },
              {
                title: "范围",
                dataIndex: "scope",
                width: 110,
                render: (s: string) => (s === "all" ? <Tag>全站</Tag> : <Tag color="purple">单用户</Tag>)
              },
              {
                title: "限定邮箱",
                dataIndex: "restrictEmail",
                width: 200,
                render: (v: string | null) => v || "-"
              },
              {
                title: "已用/上限",
                key: "uses",
                width: 110,
                render: (_: unknown, r: RedeemRow) => `${r.useCount} / ${r.maxUses}`
              },
              {
                title: "过期",
                dataIndex: "expiresAt",
                width: 168,
                render: (v: string | null) => (v ? dayjs(v).format("YYYY-MM-DD HH:mm") : "-")
              },
              {
                title: "创建时间",
                dataIndex: "createdAt",
                width: 168,
                render: (v: string) => dayjs(v).format("YYYY-MM-DD HH:mm")
              },
              {
                title: "状态",
                dataIndex: "disabled",
                width: 88,
                render: (d: boolean) => (d ? <Tag color="default">停用</Tag> : <Tag color="success">有效</Tag>)
              }
            ]}
          />
        </Card>
      </div>

      <Typography.Paragraph type="secondary" style={{ marginBottom: 0, fontSize: 12 }}>
        用户侧在「积分」页输入兑换码即可领取。失败原因示例：{Object.entries(REASON_LABEL)
          .map(([k, v]) => `${k}→${v}`)
          .join("；")}
      </Typography.Paragraph>
    </Space>
  );
};

export default AdminRedeemCodesPage;

