  const code = redeemInput.trim().toUpperCase();
  if (code.length < 4) {
    message.warning("请输入兑换码");
    return;
  }
  setRedeemLoading(true);
  (async () => {
    try {
      const res = await apiRequest<{ ok: boolean; reason: string; points?: number; balanceYuan?: number }>(
        "/api/redeem/use",
        { method: "POST", json: { code } }
      );
      if (!res.ok) {
        message.error(redeemReasonText[res.reason] || res.reason || "兑换失败");
        return;
      }
      syncFromServer({
        ...state,
        points: res.points ?? state.points,
        balanceYuan: res.balanceYuan ?? state.balanceYuan,
        signIn: state.signIn
      });
      message.success("兑换成功");
      setRedeemInput("");
    } finally {
      setRedeemLoading(false);
    }
  })().catch(() => {
    setRedeemLoading(false);
  });
};

