import { getApiBase } from "../api/client";

export function escapeHtmlText(s: string): string {
  return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}

export function escapeAttr(s: string): string {
  return escapeHtmlText(s);
}

export function resolveFeedbackAssetUrl(href: string): string {
  const u = href.trim();
  if (!u) return u;
  if (u.startsWith("http://") || u.startsWith("https://")) return u;
  const base = getApiBase().replace(/\/+$/, "");
  if (u.startsWith("/")) return `${base}${u}`;
  return `${base}/${u}`;
}

export function isSafeFeedbackImageUrl(url: string): boolean {
  const u = url.trim();
  if (!u) return false;
  const lower = u.toLowerCase();
  if (lower.startsWith("javascript:") || lower.startsWith("data:")) return false;
  if (u.startsWith("/static/feedback-uploads/")) return true;
  try {
    const p = new URL(u, "http://_");
    return p.pathname.startsWith("/static/feedback-uploads/");
  } catch {
    return false;
  }
}

/** 旧数据：纯 Markdown 或混排，转为可放进 contenteditable 的安全 HTML */
export function legacyMarkdownToEditorHtml(raw: string): string {
  if (!raw) return "";
  const re = /!\[([^\]]*)\]\(([^)]+)\)/g;
  let last = 0;
  const chunks: string[] = [];
  let m: RegExpExecArray | null;
  while ((m = re.exec(raw)) !== null) {
    if (m.index > last) {
      chunks.push(textChunkToHtmlDivs(raw.slice(last, m.index)));
    }
    const url = m[2].trim();
    if (isSafeFeedbackImageUrl(url)) {
      const src = resolveFeedbackAssetUrl(url);
      chunks.push(
        `<img src="${escapeAttr(src)}" alt="" style="max-width:100%;height:auto;display:block;margin:8px 0;border-radius:6px;"/>`
      );
    }
    last = m.index + m[0].length;
  }
  if (last < raw.length) {
    chunks.push(textChunkToHtmlDivs(raw.slice(last)));
  }
  return chunks.join("");
}

function textChunkToHtmlDivs(t: string): string {
  if (!t) return "";
  const lines = t.split(/\n/);
  return lines
    .map((line) => `<div>${line ? escapeHtmlText(line) : "<br/>"}</div>`)
    .join("");
}

export function feedbackContentLooksLikeHtml(s: string): boolean {
  return /<\s*[a-z][\s\S]*>/i.test(s);
}

/** 展示 / 回填编辑器：统一成安全 HTML（含合法 img） */
export function normalizeToEditorHtml(raw: string): string {
  if (!raw || !raw.trim()) return "";
  if (feedbackContentLooksLikeHtml(raw)) {
    return sanitizeFeedbackDisplayHtml(raw);
  }
  return legacyMarkdownToEditorHtml(raw);
}

function serializeSafeNode(node: Node): string {
  if (node.nodeType === Node.TEXT_NODE) {
    const t = node.textContent || "";
    if (!t) return "";
    return escapeHtmlText(t);
  }
  if (node.nodeType !== Node.ELEMENT_NODE) return "";
  const el = node as HTMLElement;
  const tag = el.tagName;
  if (tag === "BR") return "<br/>";
  if (tag === "IMG") {
    const src = el.getAttribute("src") || "";
    if (!isSafeFeedbackImageUrl(src)) return "";
    const abs = resolveFeedbackAssetUrl(src);
    return `<img src="${escapeAttr(abs)}" alt="" style="max-width:100%;height:auto;display:block;margin:8px 0;border-radius:6px;"/>`;
  }
  const inner = Array.from(node.childNodes).map(serializeSafeNode).join("");
  if (tag === "SPAN") return inner ? `<span>${inner}</span>` : "";
  if (tag === "P" || tag === "DIV") {
    return inner ? `<${tag.toLowerCase()}>${inner}</${tag.toLowerCase()}>` : "";
  }
  return inner;
}

/** 用于 dangerouslySetInnerHTML 与编辑器回填 */
export function sanitizeFeedbackDisplayHtml(raw: string): string {
  const doc = new DOMParser().parseFromString(raw, "text/html");
  return Array.from(doc.body.childNodes).map(serializeSafeNode).join("");
}

export function feedbackHtmlHasImage(html: string): boolean {
  return /<img[^>]*\ssrc\s*=/i.test(html) || /!\[[^\]]*\]\([^)]+\)/.test(html);
}

export function feedbackHtmlPlainTextLen(html: string): number {
  const doc = new DOMParser().parseFromString(html, "text/html");
  const t = (doc.body.textContent || "").replace(/\s+/g, " ").trim();
  return t.length;
}

import React from "react";
import { Typography } from "antd";
import {
  feedbackContentLooksLikeHtml,
  isSafeFeedbackImageUrl,
  resolveFeedbackAssetUrl,
  sanitizeFeedbackDisplayHtml
} from "./feedbackHtml";

const MD_IMG = /!\[([^\]]*)\]\(([^)]+)\)/g;

export { isSafeFeedbackImageUrl, resolveFeedbackAssetUrl } from "./feedbackHtml";

export function FeedbackContentView(props: { text: string; emptyFallback?: string }) {
  const { text, emptyFallback = "—" } = props;
  if (!text.trim()) {
    return <Typography.Text type="secondary">{emptyFallback}</Typography.Text>;
  }

  if (feedbackContentLooksLikeHtml(text)) {
    const safe = sanitizeFeedbackDisplayHtml(text);
    if (!safe.trim()) {
      return <Typography.Text type="secondary">{emptyFallback}</Typography.Text>;
    }
    return (
      <div
        className="feedback-content-view feedback-content-view--html"
        dangerouslySetInnerHTML={{ __html: safe }}
      />
    );
  }

  const nodes: React.ReactNode[] = [];
  let last = 0;
  const re = new RegExp(MD_IMG.source, "g");
  let m: RegExpExecArray | null;
  let key = 0;
  while ((m = re.exec(text)) !== null) {
    if (m.index > last) {
      nodes.push(
        <span key={key++} style={{ whiteSpace: "pre-wrap" }}>
          {text.slice(last, m.index)}
        </span>
      );
    }
    const href = m[2].trim();
    if (isSafeFeedbackImageUrl(href)) {
      const src = resolveFeedbackAssetUrl(href);
      nodes.push(
        <img
          key={key++}
          src={src}
          alt={m[1] || "image"}
          style={{ maxWidth: "100%", height: "auto", display: "block", margin: "8px 0", borderRadius: 6 }}
        />
      );
    } else {
      nodes.push(
        <Typography.Text key={key++} type="warning">
          [无效图片]
        </Typography.Text>
      );
    }
    last = m.index + m[0].length;
  }
  if (last < text.length) {
    nodes.push(
      <span key={key++} style={{ whiteSpace: "pre-wrap" }}>
        {text.slice(last)}
      </span>
    );
  }
  return <div className="feedback-content-view">{nodes}</div>;
}

import React from "react";
import { App } from "antd";
import { apiUploadFeedbackImage } from "../api/client";
import { escapeAttr, normalizeToEditorHtml, resolveFeedbackAssetUrl } from "../utils/feedbackHtml";

type Props = {
  /** 与 Form.Item 对接：首次挂载时作为初始 HTML */
  value?: string;
  onChange?: (html: string) => void;
  uploadPath: string;
  disabled?: boolean;
  placeholder?: string;
  minHeight?: number;
};

function insertNodeAtCaret(root: HTMLElement, node: Node) {
  const sel = window.getSelection();
  if (!sel || sel.rangeCount === 0 || !root.contains(sel.anchorNode)) {
    root.appendChild(node);
    return;
  }
  const range = sel.getRangeAt(0);
  range.deleteContents();
  range.insertNode(node);
  range.setStartAfter(node);
  range.collapse(true);
  sel.removeAllRanges();
  sel.addRange(range);
}

/**
 * 所见即所得：截图粘贴后以 <img> 显示在编辑区内（存储为 HTML，不再使用 Markdown 链接）。
 */
export const FeedbackRichEditor: React.FC<Props> = (props) => {
  const { value, onChange, uploadPath, disabled, placeholder, minHeight = 220 } = props;
  const { message } = App.useApp();
  const ref = React.useRef<HTMLDivElement>(null);
  const initHtmlRef = React.useRef<string | null>(null);
  if (initHtmlRef.current === null) {
    initHtmlRef.current = normalizeToEditorHtml(value ?? "");
  }

  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    el.innerHTML = initHtmlRef.current || "";
  }, []);

  const emit = React.useCallback(() => {
    const el = ref.current;
    if (!el) return;
    onChange?.(el.innerHTML);
  }, [onChange]);

  const onPaste = React.useCallback(
    async (e: React.ClipboardEvent<HTMLDivElement>) => {
      const items = e.clipboardData?.items;
      if (!items?.length) return;
      for (let i = 0; i < items.length; i++) {
        const it = items[i];
        if (it.kind === "file" && it.type.startsWith("image/")) {
          e.preventDefault();
          const file = it.getAsFile();
          if (!file || disabled) return;
          const root = ref.current;
          if (!root) return;
          try {
            message.loading({ content: "正在上传截图…", key: "fb-up", duration: 0 });
            const { url } = await apiUploadFeedbackImage(uploadPath, file);
            message.destroy("fb-up");
            const src = resolveFeedbackAssetUrl(url);
            const img = document.createElement("img");
            img.src = src;
            img.alt = "";
            img.style.maxWidth = "100%";
            img.style.height = "auto";
            img.style.display = "block";
            img.style.margin = "8px 0";
            img.style.borderRadius = "6px";
            insertNodeAtCaret(root, img);
            const br = document.createElement("br");
            insertNodeAtCaret(root, br);
            emit();
            message.success("图片已插入");
          } catch (err) {
            message.destroy("fb-up");
            const d =
              typeof err === "object" && err && "detail" in err ? String((err as { detail?: string }).detail) : "";
            message.error(d || "图片上传失败");
          }
          return;
        }
      }
    },
    [disabled, emit, message, uploadPath]
  );

  return (
    <div className="feedback-rich-editor-shell">
      <div
        ref={ref}
        className="feedback-rich-editor"
        contentEditable={!disabled}
        suppressContentEditableWarning
        data-placeholder={placeholder || ""}
        style={{ minHeight }}
        onInput={emit}
        onBlur={emit}
        onPaste={onPaste}
      />
    </div>
  );
};

