import type { NavigateFunction } from "react-router-dom";
import { clearAdminSession, isAdminByEmail, setAdminSession } from "../state/adminAuth";

const SESSION_REDIRECT_KEY = "paper-polish.post-login-redirect.v1";

/** 401 等整页跳转前写入，登录成功后消费（与 React Router state.from 二选一） */
export function stashPostLoginRedirect(path: string): void {
  try {
    if (path && path.startsWith("/")) sessionStorage.setItem(SESSION_REDIRECT_KEY, path);
  } catch {
    /* ignore */
  }
}

export function consumePostLoginRedirect(): string | null {
  try {
    const v = sessionStorage.getItem(SESSION_REDIRECT_KEY);
    sessionStorage.removeItem(SESSION_REDIRECT_KEY);
    return v && v.startsWith("/") ? v : null;
  } catch {
    return null;
  }
}

/**
 * 登录成功后：管理员进 /admin 目标或仪表盘，普通用户进控制台。
 * `locationState` 可为 `useLocation().state`，含 `{ from?: string }`（如从 AdminRouteGuard 传来）。
 */
export function navigateAfterLogin(navigate: NavigateFunction, email: string, locationState: unknown): void {
  const normalized = email.trim().toLowerCase();
  const fromState = (locationState as { from?: string } | null)?.from;
  const fromStored = consumePostLoginRedirect();
  const from =
    fromState && typeof fromState === "string" && fromState.startsWith("/") ? fromState : fromStored;

  if (isAdminByEmail(normalized)) {
    setAdminSession(normalized);
    if (from && from.startsWith("/admin")) {
      navigate(from, { replace: true });
    } else {
      navigate("/admin/dashboard", { replace: true });
    }
  } else {
    clearAdminSession();
    navigate("/console/dashboard", { replace: true });
  }
}

import React from "react";
import { App, Spin } from "antd";
import { Navigate, Outlet, useLocation } from "react-router-dom";
import { apiRequest, getAccessToken } from "../api/client";
import { isAdminByEmail, setAdminSession } from "../state/adminAuth";

type Me = { id: string; email: string; nickname?: string | null };

const AdminRouteGuard: React.FC = () => {
  const location = useLocation();
  const { message } = App.useApp();
  const [phase, setPhase] = React.useState<"loading" | "ok" | "login" | "forbidden">("loading");

  React.useEffect(() => {
    const token = getAccessToken();
    if (!token) {
      setPhase("login");
      return;
    }
    let cancelled = false;
    apiRequest<Me>("/api/auth/me", { method: "GET" })
      .then((me) => {
        if (cancelled) return;
        const email = (me.email || "").trim().toLowerCase();
        if (isAdminByEmail(email)) {
          setAdminSession(email);
          setPhase("ok");
        } else {
          message.warning("当前账号无管理员权限");
          setPhase("forbidden");
        }
      })
      .catch(() => {
        if (!cancelled) setPhase("login");
      });
    return () => {
      cancelled = true;
    };
  }, [message]);

  if (phase === "loading") {
    return (
      <div style={{ display: "flex", justifyContent: "center", alignItems: "center", minHeight: "40vh" }}>
        <Spin size="large" tip="校验管理员权限…" />
      </div>
    );
  }
  if (phase === "login") {
    return (
      <Navigate
        to="/login"
        replace
        state={{ from: `${location.pathname}${location.search || ""}` }}
      />
    );
  }
  if (phase === "forbidden") {
    return <Navigate to="/console/dashboard" replace />;
  }
  return <Outlet />;
};

export default AdminRouteGuard;

